// Typed shim over the generated FDC bundle. The JSON is generated by
// scripts/import/build-fdc-bundle.ts and is loaded once at module init.
import bundle from "./fdc-foods.json" assert { type: "json" };

export interface FdcFood {
  id: number;
  desc: string;
  kcal: number;
  p: number;
  f: number;
  c: number;
  fb: number;
  cat: string | null;
  src: "F" | "S";
}

interface FdcAliasRefRaw {
  id: number;
  approx: boolean;
  portion: number | null;
  note: string | null;
}

export interface FdcAliasEntry {
  food: FdcFood;
  approx: boolean;
  portion: number | null;
  note: string | null;
}

const raw = bundle as { foods: FdcFood[]; aliases: Record<string, FdcAliasRefRaw> };

export const FDC_FOODS: FdcFood[] = raw.foods;

export const FDC_BY_ID: Map<number, FdcFood> = new Map(
  FDC_FOODS.map((f) => [f.id, f]),
);

export const FDC_ALIAS_INDEX: Map<string, FdcAliasEntry> = (() => {
  const m = new Map<string, FdcAliasEntry>();
  for (const [name, ref] of Object.entries(raw.aliases)) {
    const food = FDC_BY_ID.get(ref.id);
    if (!food) continue;
    m.set(name, { food, approx: ref.approx, portion: ref.portion, note: ref.note });
  }
  return m;
})();